import { isAxiosError } from 'axios';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router';
import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Snackbar,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import type { SelectChangeEvent } from '@mui/material';
import {
  deleteTableRow,
  getTableColumns,
  getTables,
  listTableRows,
  updateTableRow,
} from '~/services/api';
import type { Column } from '~/services/api';

export function meta() {
  return [{ title: 'Data Browser - LearningDB' }];
}

function apiDetail(err: unknown): string {
  if (isAxiosError(err)) {
    const d = err.response?.data;
    if (typeof d === 'object' && d !== null && 'detail' in d) {
      return String((d as { detail: unknown }).detail);
    }
  }
  return err instanceof Error ? err.message : 'Request failed';
}

function formatCell(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function coerceValue(sqlType: string, raw: string): unknown {
  const t = sqlType.toLowerCase();
  const trimmed = raw.trim();
  if (trimmed === '') return null;
  if (t.includes('int') || t === 'year') {
    const n = parseInt(trimmed, 10);
    if (!Number.isNaN(n)) return n;
  }
  if (
    t.includes('decimal') ||
    t.includes('float') ||
    t.includes('double') ||
    t.includes('numeric')
  ) {
    const n = parseFloat(trimmed);
    if (!Number.isNaN(n)) return n;
  }
  return raw;
}

function pickPrimaryKey(
  row: Record<string, unknown>,
  columns: Column[],
): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const col of columns) {
    if (col.is_primary_key) {
      out[col.name] = row[col.name];
    }
  }
  return out;
}

function hasPrimaryKey(columns: Column[]): boolean {
  return columns.some((c) => c.is_primary_key);
}

export default function DataBrowser() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [searchParams, setSearchParams] = useSearchParams();

  const [tables, setTables] = useState<string[]>([]);
  const [selectedTable, setSelectedTable] = useState('');
  const [columns, setColumns] = useState<Column[]>([]);
  const [rows, setRows] = useState<Record<string, unknown>[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(25);
  const [sortBy, setSortBy] = useState<string>('');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  const [filterDraft, setFilterDraft] = useState<Record<string, string>>({});
  const [appliedFilters, setAppliedFilters] = useState<Record<string, unknown>>({});

  const [loadingTables, setLoadingTables] = useState(false);
  const [loadingData, setLoadingData] = useState(false);
  const [snackbar, setSnackbar] = useState<{
    open: boolean;
    message: string;
    severity: 'success' | 'error';
  }>({ open: false, message: '', severity: 'success' });

  const [editOpen, setEditOpen] = useState(false);
  const [editForm, setEditForm] = useState<Record<string, string>>({});
  const [editRow, setEditRow] = useState<Record<string, unknown> | null>(null);

  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleteRow, setDeleteRow] = useState<Record<string, unknown> | null>(null);

  const columnNames = useMemo(() => columns.map((c) => c.name), [columns]);

  const loadTables = useCallback(async () => {
    setLoadingTables(true);
    try {
      const res = await getTables();
      setTables(res.data.tables);
    } catch (err) {
      console.error(err);
      setSnackbar({ open: true, message: apiDetail(err), severity: 'error' });
    } finally {
      setLoadingTables(false);
    }
  }, []);

  useEffect(() => {
    void loadTables();
  }, [loadTables]);

  // Sync table from URL once tables are loaded
  useEffect(() => {
    if (!tables.length) return;
    const want = searchParams.get('table');
    if (!want) return;
    const match = tables.find((x) => x.toLowerCase() === want.toLowerCase());
    if (match && match !== selectedTable) {
      setSelectedTable(match);
    }
  }, [tables, searchParams, selectedTable]);

  // Sync filters from URL (once per navigation)
  useEffect(() => {
    const raw = searchParams.get('filters');
    if (!raw) return;
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) return;
      const draft: Record<string, string> = {};
      for (const [k, v] of Object.entries(parsed)) {
        draft[k] = v === null || v === undefined ? '' : String(v);
      }
      setFilterDraft((prev) => ({ ...prev, ...draft }));
      setAppliedFilters(parsed as Record<string, unknown>);
    } catch {
      /* ignore */
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only when filters param changes
  }, [searchParams.get('filters')]);

  const loadColumns = useCallback(async (tableName: string) => {
    if (!tableName) {
      setColumns([]);
      return;
    }
    try {
      const res = await getTableColumns(tableName);
      setColumns(res.data.columns);
      const emptyDraft: Record<string, string> = {};
      res.data.columns.forEach((c) => {
        emptyDraft[c.name] = filterDraft[c.name] ?? '';
      });
      setFilterDraft((prev) => {
        const next = { ...emptyDraft };
        for (const k of Object.keys(next)) {
          if (prev[k] !== undefined) next[k] = prev[k];
        }
        return next;
      });
    } catch (err) {
      console.error(err);
      setColumns([]);
      setSnackbar({ open: true, message: apiDetail(err), severity: 'error' });
    }
  }, []);

  useEffect(() => {
    if (!selectedTable) {
      setColumns([]);
      setRows([]);
      setTotal(0);
      return;
    }
    void loadColumns(selectedTable);
  }, [selectedTable, loadColumns]);

  const fetchRows = useCallback(async () => {
    if (!selectedTable) return;
    setLoadingData(true);
    try {
      const res = await listTableRows(selectedTable, {
        limit: rowsPerPage,
        offset: page * rowsPerPage,
        sort_by: sortBy || null,
        sort_dir: sortDir,
        filters: appliedFilters,
      });
      setRows(res.data.rows);
      setTotal(res.data.total);
    } catch (err) {
      console.error(err);
      setRows([]);
      setTotal(0);
      setSnackbar({ open: true, message: apiDetail(err), severity: 'error' });
    } finally {
      setLoadingData(false);
    }
  }, [selectedTable, page, rowsPerPage, sortBy, sortDir, appliedFilters]);

  useEffect(() => {
    if (!selectedTable || !columns.length) {
      return;
    }
    void fetchRows();
  }, [selectedTable, columns.length, fetchRows]);

  const handleTableChange = (event: SelectChangeEvent) => {
    const name = event.target.value;
    setSelectedTable(name);
    setPage(0);
    setSortBy('');
    setAppliedFilters({});
    setFilterDraft({});
    setSearchParams((prev) => {
      const p = new URLSearchParams(prev);
      if (name) p.set('table', name);
      else p.delete('table');
      p.delete('filters');
      return p;
    });
  };

  const applyFilters = () => {
    const built: Record<string, unknown> = {};
    for (const col of columns) {
      const raw = (filterDraft[col.name] ?? '').trim();
      if (raw === '') continue;
      built[col.name] = coerceValue(col.type, raw);
    }
    setAppliedFilters(built);
    setPage(0);
    setSearchParams((prev) => {
      const p = new URLSearchParams(prev);
      if (selectedTable) p.set('table', selectedTable);
      if (Object.keys(built).length) p.set('filters', JSON.stringify(built));
      else p.delete('filters');
      return p;
    });
  };

  const clearFilters = () => {
    const empty: Record<string, string> = {};
    columns.forEach((c) => {
      empty[c.name] = '';
    });
    setFilterDraft(empty);
    setAppliedFilters({});
    setPage(0);
    setSearchParams((prev) => {
      const p = new URLSearchParams(prev);
      if (selectedTable) p.set('table', selectedTable);
      p.delete('filters');
      return p;
    });
  };

  const openEdit = (row: Record<string, unknown>) => {
    setEditRow(row);
    const form: Record<string, string> = {};
    columns.forEach((c) => {
      form[c.name] = formatCell(row[c.name]);
    });
    setEditForm(form);
    setEditOpen(true);
  };

  const saveEdit = async () => {
    if (!selectedTable || !editRow || !columns.length) return;
    const pk = pickPrimaryKey(editRow, columns);
    const updates: Record<string, unknown> = {};
    for (const col of columns) {
      if (col.is_primary_key) continue;
      const raw = editForm[col.name] ?? '';
      updates[col.name] = coerceValue(col.type, raw);
    }
    setLoadingData(true);
    try {
      await updateTableRow(selectedTable, pk, updates);
      setSnackbar({ open: true, message: 'Row updated', severity: 'success' });
      setEditOpen(false);
      await fetchRows();
    } catch (err) {
      setSnackbar({ open: true, message: apiDetail(err), severity: 'error' });
    } finally {
      setLoadingData(false);
    }
  };

  const confirmDelete = async () => {
    if (!selectedTable || !deleteRow || !columns.length) return;
    const pk = pickPrimaryKey(deleteRow, columns);
    setLoadingData(true);
    try {
      await deleteTableRow(selectedTable, pk);
      setSnackbar({ open: true, message: 'Row deleted', severity: 'success' });
      setDeleteOpen(false);
      setDeleteRow(null);
      await fetchRows();
    } catch (err) {
      setSnackbar({ open: true, message: apiDetail(err), severity: 'error' });
    } finally {
      setLoadingData(false);
    }
  };

  const pkOk = hasPrimaryKey(columns);

  return (
    <>
      <Stack spacing={2}>
        <Typography variant="h5" gutterBottom>
          Data browser
        </Typography>
        <Typography variant="body2" color="text.secondary">
          View, edit, and delete rows with server-side filters, sort, and pagination. Dangerous on production
          data; use TABLE_BROWSER_DENYLIST on the server if needed.
        </Typography>

        <FormControl size="small" sx={{ minWidth: isMobile ? '100%' : 280 }}>
          <InputLabel>Table</InputLabel>
          <Select
            label="Table"
            value={selectedTable}
            onChange={handleTableChange}
            disabled={loadingTables}
          >
            <MenuItem value="">
              <em>Select a table</em>
            </MenuItem>
            {tables.map((t) => (
              <MenuItem key={t} value={t}>
                {t}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        {selectedTable && columns.length > 0 && (
          <>
            <Typography variant="subtitle2">Filters (equality)</Typography>
            <Box
              sx={{
                display: 'grid',
